head.script:
requires("externalJS/big/big.min.js");

scwin.expected = "469135800246913580024691358002";

scwin.stringify = function(value) {
    if (value == null) {
        return value;
    }
    return value.toString ? value.toString() : String(value);
};

scwin.resetGridExpression = function() {
    var cellInfo = gridView1 && gridView1.getCellInfo("calcGrid");
    if (cellInfo) {
        cellInfo.options.expressionFunc = null;
    }
};

scwin.refreshGridExpression = function() {
    scwin.resetGridExpression();
    if (gridView1 && gridView1.refresh) {
        gridView1.refresh();
    }
};

scwin.isBigReady = function() {
    try {
        var value = WebSquare.bigDecimal("1");
        return !!(value && value.big && typeof value.big.plus === "function");
    } catch (e) {
        return false;
    }
};

scwin.refreshWhenBigReady = function(retryCount) {
    retryCount = retryCount || 0;
    if (scwin.isBigReady()) {
        scwin.refreshGridExpression();
        return;
    }
    if (retryCount < 100) {
        setTimeout(function() {
            scwin.refreshWhenBigReady(retryCount + 1);
        }, 50);
    }
};

scwin.calcGrid = function(rowIndex) {
    if (!scwin.isBigReady()) {
        return "";
    }
    if (!dataList1 || !dataList1.getRowCount || rowIndex == null || rowIndex < 0 || rowIndex >= dataList1.getRowCount()) {
        return "";
    }
    if (!dataList1.getCellData(rowIndex, "a") || !dataList1.getCellData(rowIndex, "b") || !dataList1.getCellData(rowIndex, "c")) {
        return "";
    }
    return gridView1.getCellInfo("calcGrid").colcalc(rowIndex, "(a+b)*c");
};

scwin.onpageload = function() {
    dataList1.setJSON([
        {
            "a": "123456789012345678901234567890",
            "b": "111111111111111111111111111111",
            "c": "2"
        },
        {
            "a": "1",
            "b": "2",
            "c": "3"
        }
    ]);
    scwin.refreshWhenBigReady();
};

scwin.getExpressionSnapshot = function(rowIndex) {
    if (!scwin.isBigReady()) {
        return {
            gridExpression: "",
            gridDisplay: "",
            dataListExpression: ""
        };
    }
    scwin.resetGridExpression();
    var gridCellInfo = gridView1.getCellInfo("calcGrid");
    var dataListCellInfo = dataList1.getCellInfo("calcData");
    var gridExpression = gridCellInfo.getExpressionValue(rowIndex);
    var dataListExpression = dataListCellInfo.getExpressionValue(rowIndex);

    return {
        gridExpression: scwin.stringify(gridExpression),
        gridDisplay: scwin.stringify(gridView1.getCellDisplayData(rowIndex, "calcGrid")),
        dataListExpression: scwin.stringify(dataListExpression)
    };
};

scwin.setValues = function(rowIndex, a, b, c) {
    dataList1.setCellData(rowIndex, "a", a);
    dataList1.setCellData(rowIndex, "b", b);
    dataList1.setCellData(rowIndex, "c", c);
    scwin.refreshGridExpression();
    return scwin.getExpressionSnapshot(rowIndex);
};
